<?php

namespace App\Http\Controllers;

use Auth;

use App\ProdutoLinha;
use App\ProdutoEspecificacao;
use App\Movimentacao;

use Illuminate\Http\Request;

use App\Http\Requests\ProdutoLinhaAdicionarRequest;
use App\Http\Requests\ProdutoLinhaEditarRequest;

class ProdutoLinhaController extends Controller
{
    public function index(Request $request){
        if(Auth::user()->hasPermissionTo("programas App\ProdutoLinha") === false){
            return abort(403);
        }
        $request->session()->flash('model', 'App\ProdutoLinha');

        return view('programs.produto.linha.index');
    }

    public function modalAdicionar() {
        return view('programs.produto.linha.modal.adicionar');
    }

    public function adicionar(ProdutoLinhaAdicionarRequest $request) {
        $fields = $request->only('linha');
        $linha = strtoupper(tirarAcentos($fields['linha']));

        $linhaObj = new ProdutoLinha;
        $linhaObj->descricao = $linha;
        $linhaObj->created_by = Auth::id();
        $linhaObj->save();

        $response = [
            "status" => 'success',
            "message" => '',
            "error" => [],
            "response" => []
        ];
        return response()->json($response);
    }

    public function modalEditar(Request $request){
        $id = $request->only(['id'])['id'];
        try{
            $id = decrypt($id);
        }catch(\Exception $e){
            return response()->json([
                'status' => 'error',
                'message' => 'Dados não encontrados',
                'error' => [],
                'response' => []
            ]);
        }

        $query = ProdutoLinha::select();
        $query->where('id', '=', $id);
        if(is_null($query)){
            return response()->json([
                'status' => 'error',
                'message' => 'Motivo não econtrado',
                'error' => '',
                'response' => ''
            ]);
        }
        $result = $query->first();
       
        $dados = [
            'id' => encrypt($result->id),
            'linha' => $result->descricao
        ];

        return view('programs.produto.linha.modal.editar')->with(['dados' => $dados]);
    }

    public function editar(ProdutoLinhaEditarRequest $request){
        $fields = $request->only('id','linha');
        $linha = strtoupper(tirarAcentos($fields['linha']));
        try{
            $id = decrypt($fields['id']);
        }catch(\Exception $e){
            return response()->json([
                'status' => 'error',
                'message' => 'Dados não encontrados',
                'error' => [],
                'response' => []
            ]);
        }

        $linhaObj = ProdutoLinha::find($id);

        $linha_antigo = $linhaObj->descricao;
        $produtoEspecificacaoObj = ProdutoEspecificacao::select(); 
        $produtoEspecificacaoObj->where('linha', $linha_antigo);
        $produtoEspecificacaoObj->update(['linha' => $linha]);

        $linhaObj->descricao = $linha;
        $linhaObj->updated_by = Auth::id();
        $linhaObj->save();

        $response = [
            "status" => 'success',
            "message" => '',
            "error" => [],
            "response" => []
        ];
        return response()->json($response);
    }

    public function modalDeletar(Request $request){
        $id = $request->only(['id'])['id'];
        
        try{
            $id = decrypt($id);
        }catch(\Exception $e){
            return response()->json([
                'status' => 'error',
                'message' => 'Dados não encontrados',
                'error' => [],
                'response' => []
            ]);
        }
        $query = ProdutoLinha::select();
        $query->where('id', '=', $id);
        if(is_null($query)){
            return response()->json([
                'status' => 'error',
                'message' => 'Motivo não econtrado',
                'error' => '',
                'response' => ''
            ]);
        }
        $result = $query->first();

        $quantidade = ProdutoEspecificacao::where('linha', $result->descricao)->count(); 

        $dados = [
            'id' => encrypt($result->id),
            'linha' => $result->descricao
        ];

        return view('programs.produto.linha.modal.deletar')->with(['dados' => $dados, 'quantidade' => $quantidade]);
    }

    public function deletar(Request $request){
        $id = $request->only(['id'])['id'];
        try{
            $id = decrypt($id);
        }catch(\Exception $e){
            return response()->json([
                'status' => 'error',
                'message' => 'Dados não encontrados',
                'error' => [],
                'response' => []
            ]);
        }
        
        
        $linhaObj = ProdutoLinha::find($id);
        $linhaObj->deleted_by = Auth::id();
        $linhaObj->save();
        $linhaObj->delete();

        $response = [
            "status" => 'success',
            "message" => '',
            "error" => [],
            "response" => []
        ];
        return response()->json($response);
    }

    public function filter(Request $request){
        $fields = $request->only('linha');
        $linha = strtoupper(tirarAcentos($fields['linha']));
        $retorno = [];

        $query = ProdutoLinha::select();
        if(!empty($linha)){
            $query->where('descricao', 'like', '%'.$linha.'%');
        }
        $result = $query->get();

        foreach($result as $linha){
            $retorno [] = [
                'id' => encrypt($linha->id),
                'descricao' => $linha->descricao
            ];
        }

        $response = [
            "status" => 'success',
            "message" => '',
            "error" => [],
            "response" => $retorno
        ];
        return response()->json($response);
    }

    public function autoComplete(Request $request){
        $descricao = $request->only('term');
        $return = [];
        $query = ProdutoLinha::select('descricao')
            ->limit("15")
            ->orderBy('descricao', "ASC")
            ->where('descricao', 'ilike', '%'.$descricao['term'].'%')
            ->distinct('descricao')
            ->get()
            ->toArray();
        foreach ($query as $value){
            $value = (array) $value;
            $return[] = trim($value['descricao']);
        }

        return response()->json($return);
    }

